sections.content:
// Cupertino-стиль (по умолчанию на iOS)
Navigator.push(
context,
CupertinoPageRoute(
builder: (context) => const NextScreen(),
),
);

class CustomPageRoute<T> extends PageRoute<T> {
final Widget child;
final Duration duration;

CustomPageRoute({
required this.child,
this.duration = const Duration(milliseconds: 300),
});

@override
bool get maintainState => true;

@override
bool get opaque => true;

@override
Color? get barrierColor => null;

@override
String? get barrierLabel => null;

@override
Widget buildTransitions(
BuildContext context,
Animation<double> animation,
Animation<double> secondaryAnimation,
Widget child,
) {
// Анимация появления слева
return SlideTransition(
position: Tween<Offset>(
begin: const Offset(-1, 0),
end: Offset.zero,
).animate(CurvedAnimation(
parent: animation,
curve: Curves.easeOutCubic,
)),
child: child,
);
}

@override
Widget buildContent(BuildContext context) => child;

@override
Widget buildPage(
BuildContext context,
Animation<double> animation,
Animation<double> secondaryAnimation,
) =>
child;
}

// Использование
Navigator.push(
context,
CustomPageRoute(child: const NextScreen()),
);

class RouteBuilderExample extends StatelessWidget {
const RouteBuilderExample({super.key});

@override
Widget build(BuildContext context) {
return Scaffold(
appBar: AppBar(title: const Text('Route Builder')),
body: Center(
child: ElevatedButton(
onPressed: () {
Navigator.push(
context,
PageRouteBuilder(
pageBuilder: (context, animation, secondaryAnimation) {
return const NextScreen();
},
transitionsBuilder: (context, animation, secondaryAnimation, child) {
// Комбинированные анимации
return SlideTransition(
position: Tween<Offset>(
begin: const Offset(0, 1),
end: Offset.zero,
).animate(CurvedAnimation(
parent: animation,
curve: Curves.easeOutCubic,
)),
child: FadeTransition(
opacity: animation,
child: child,
),
);
},
transitionDuration: const Duration(milliseconds: 400),
reverseTransitionDuration: const Duration(milliseconds: 300),
),
);
},
child: const Text('Перейти'),
),
),
);
}
}

// Справа налево (Material стандарт)
SlideTransition(
position: Tween<Offset>(
begin: const Offset(1, 0),
end: Offset.zero,
).animate(CurvedAnimation(
parent: animation,
curve: Curves.easeOutCubic,
)),
child: child,
)

// Снизу вверх
SlideTransition(
position: Tween<Offset>(
begin: const Offset(0, 1),
end: Offset.zero,
).animate(CurvedAnimation(
parent: animation,
curve: Curves.easeOutCubic,
)),
child: child,
)

// Сверху вниз
SlideTransition(
position: Tween<Offset>(
begin: const Offset(0, -1),
end: Offset.zero,
).animate(CurvedAnimation(
parent: animation,
curve: Curves.easeOutCubic,
)),
child: child,
)

// Сверху вниз (pop)
SlideTransition(
position: Tween<Offset>(
begin: Offset.zero,
end: const Offset(0, -1),
).animate(CurvedAnimation(
parent: animation,
curve: Curves.easeOutCubic,
)),
child: child,
)

ScaleTransition(
scale: Tween<double>(
begin: 0.8,
end: 1.0,
).animate(CurvedAnimation(
parent: animation,
curve: Curves.easeOutBack,
)),
child: child,
)

RotateTransition(
turns: Tween<double>(
begin: 0.0,
end: 1.0,
).animate(CurvedAnimation(
parent: animation,
curve: Curves.easeInOut,
)),
child: child,
)

// Комбинация нескольких анимаций
SlideTransition(
position: Tween<Offset>(
begin: const Offset(0, 0.1),
end: Offset.zero,
).animate(CurvedAnimation(
parent: animation,
curve: Curves.easeOutCubic,
)),
child: FadeTransition(
opacity: Tween<double>(
begin: 0.0,
end: 1.0,
).animate(CurvedAnimation(
parent: animation,
curve: Curves.easeIn,
)),
child: ScaleTransition(
scale: Tween<double>(
begin: 0.95,
end: 1.0,
).animate(CurvedAnimation(
parent: animation,
curve: Curves.easeOutCubic,
)),
child: child,
),
),
)

class SharedAxisTransition extends PageTransitionsTheme {
@override
Widget build(
BuildContext context,
double animation,
double secondaryAnimation,
Directionality textDirection,
Widget child,
) {
final offsetTween = Tween<Offset>(
begin: const Offset(1, 0),
end: Offset.zero,
);

return SlideTransition(
position: offsetTween.animate(
CurvedAnimation(
parent: animation,
curve: Curves.easeOutCubic,
),
),
child: child,
);
}
}

class VerticalSharedAxisTransition extends PageTransitionsTheme {
@override
Widget build(
BuildContext context,
double animation,
double secondaryAnimation,
Directionality textDirection,
Widget child,
) {
final offsetTween = Tween<Offset>(
begin: const Offset(0, 1),
end: Offset.zero,
);

return SlideTransition(
position: offsetTween.animate(
CurvedAnimation(
parent: animation,
curve: Curves.easeOutCubic,
),
),
child: child,
);
}
}

void main() {
runApp(
MaterialApp(
theme: ThemeData(
pageTransitionsTheme: PageTransitionsTheme(
builders: {
TargetPlatform.android: SharedAxisTransition(),
TargetPlatform.iOS: CupertinoPageTransitionsBuilder(),
},
),
),
home: const HomeScreen(),
),
);
}
